import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const sprintDir = dirname(fileURLToPath(import.meta.url));

const esc = (value) =>
  String(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;");

function shell({ story, title, version, height, body, desc }) {
  return `<svg xmlns="http://www.w3.org/2000/svg" width="1440" height="${height}" viewBox="0 0 1440 ${height}">
  <title>Cup Flow Coffee POS — ${esc(story)} ${esc(title)}</title>
  <desc>${esc(desc)}</desc>
  <defs>
    <style>
      text{font-family:"PingFang SC","Microsoft YaHei",sans-serif;fill:#1D2129}.h1{font-size:30px;font-weight:600}.h2{font-size:24px;font-weight:600}.h3{font-size:18px;font-weight:600}.title{font-size:28px;font-weight:700}.body{font-size:14px}.medium{font-size:14px;font-weight:500}.small{font-size:12px;fill:#6B7785}.tiny{font-size:11px;fill:#6B7785}.white{fill:#FFF}.secondary{fill:#4E5969}.muted{fill:#6B7785}.error{fill:#DC2626}.success{fill:#15803D}.warning{fill:#B45309}.info{fill:#2563EB}.section{fill:#FFF;stroke:#E5E6EB}.card{fill:#FFF;stroke:#E5E6EB}.line{stroke:#E5E6EB}
    </style>
    <filter id="shadow" x="-20%" y="-20%" width="140%" height="160%"><feDropShadow dx="0" dy="6" stdDeviation="14" flood-color="#1D2129" flood-opacity=".14"/></filter>
    <symbol id="check" viewBox="0 0 20 20"><path d="M4.5 10.5L8.3 14L15.5 6.5" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></symbol>
    <symbol id="x" viewBox="0 0 20 20"><path d="M5 5L15 15M15 5L5 15" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/></symbol>
  </defs>
  <rect width="1440" height="${height}" fill="#F7F8FA"/>
  <g id="cover"><rect width="1440" height="152" fill="#1D2129"/><rect x="64" y="42" width="12" height="64" rx="6" fill="#DD2089"/><text x="96" y="72" class="h1 white">Cup Flow Coffee POS</text><text x="96" y="106" class="body" style="fill:#C9CDD4">${esc(story)} · ${esc(title)} · SVG handoff</text><text x="1376" y="70" class="medium" text-anchor="end" style="fill:#FDC2DB">${esc(version)}</text><text x="1376" y="100" class="small" text-anchor="end" style="fill:#C9CDD4">Desktop 1280×800 · 2026-08-17</text></g>
  ${body}
  <text x="720" y="${height - 26}" class="tiny" text-anchor="middle">Cup Flow Coffee POS · ${esc(story)} · Import SVG to Figma and convert frame-* groups to Frames</text>
</svg>\n`;
}

function principles(title, subtitle, items) {
  return `<g id="principles" transform="translate(64 184)"><rect width="1312" height="224" rx="16" class="section"/><text x="24" y="42" class="h2">${esc(title)}</text><text x="24" y="72" class="body secondary">${esc(subtitle)}</text><g transform="translate(24 98)">${items
    .map((item, index) => {
      const x = index * 316;
      return `<rect x="${x}" width="300" height="78" rx="12" fill="#F2F3F5"/><circle cx="${x + 36}" cy="39" r="18" fill="${index === 3 ? "#DD2089" : "#1D2129"}"/><text x="${x + 36}" y="44" class="medium white" text-anchor="middle">0${index + 1}</text><text x="${x + 66}" y="32" class="medium">${esc(item[0])}</text><text x="${x + 66}" y="55" class="small">${esc(item[1])}</text>`;
    })
    .join("")}</g><text x="24" y="204" class="small">品牌粉仅用于品牌标识；主动作、选中和 Focus Visible 使用 #1D2129。</text></g>`;
}

function sectionTitle(y, number, title, note = "") {
  return `<text x="64" y="${y}" class="h2">${number}  ${esc(title)}</text><text x="1376" y="${y}" class="small" text-anchor="end">${esc(note)}</text>`;
}

function option(x, y, w, label, selected = false, disabled = false, sub = "") {
  const fill = selected || disabled ? "#F2F3F5" : "#FFFFFF";
  const stroke = selected ? "#1D2129" : disabled ? "#E5E6EB" : "#C9CDD4";
  const text = disabled ? "#86909C" : "#1D2129";
  return `<g transform="translate(${x} ${y})"><rect width="${w}" height="52" rx="10" fill="${fill}" stroke="${stroke}" stroke-width="${selected ? 2 : 1}"/><text x="16" y="${sub ? 23 : 32}" class="medium" style="fill:${text}">${esc(label)}</text>${sub ? `<text x="16" y="42" class="small">${esc(sub)}</text>` : ""}${selected ? `<circle cx="${w - 20}" cy="16" r="10" fill="#1D2129"/><g transform="translate(${w - 27} 9)" style="color:#FFF"><use href="#check" width="14" height="14"/></g>` : ""}</g>`;
}

